class Solution {
    public int findMinimumOperations(String s1, String s2, String s3) {
        int L = 0, m = Math.min(s1.length(), Math.min(s2.length(), s3.length()));
        while (L < m && s1.charAt(L) == s2.charAt(L) && s2.charAt(L) == s3.charAt(L)) L++;
        if (L == 0) return -1;
        return s1.length() + s2.length() + s3.length() - 3 * L;
    }
}

